const game = new GF.Game({
  id: 'core-awakening',
  title: 'Core Awakening',
  width: 960,
  height: 540,
  palette: ['#00FFFF', '#A0A0A0', '#FF8000', '#404040'],
  background: '#101010',
  seed: 42
});

const player = {
  x: game.W / 2,
  y: game.H / 2,
  vx: 0,
  vy: 0,
  speed: 200,
  radius: 15,
  color: '#00FFFF',
  health: 100
};

const enemies = [];
const particles = new GF.Particles();

function createEnemy() {
  const x = Math.random() > 0.5 ? 0 : game.W;
  const y = Math.random() * game.H;
  const speed = 50 + Math.random() * 50;
  const radius = 20 + Math.random() * 10;
  const color = '#FF8000';
  enemies.push({ x, y, speed, radius, color, vx: 0, vy: 0 });
}

function updatePlayer(dt) {
  const input = game.input;
  player.vx = (input.keys['ArrowRight'] || input.keys['KeyD'] ? 1 : 0) - (input.keys['ArrowLeft'] || input.keys['KeyA'] ? 1 : 0);
  player.vy = (input.keys['ArrowDown'] || input.keys['KeyS'] ? 1 : 0) - (input.keys['ArrowUp'] || input.keys['KeyW'] ? 1 : 0);
  const mag = Math.hypot(player.vx, player.vy);
  if (mag > 0) {
    player.vx *= player.speed * dt / mag;
    player.vy *= player.speed * dt / mag;
  }
  player.x = GF.math.clamp(player.x + player.vx, player.radius, game.W - player.radius);
  player.y = GF.math.clamp(player.y + player.vy, player.radius, game.H - player.radius);
}

function updateEnemies(dt) {
  for (const enemy of enemies) {
    const angle = Math.atan2(player.y - enemy.y, player.x - enemy.x);
    enemy.vx = Math.cos(angle) * enemy.speed * dt;
    enemy.vy = Math.sin(angle) * enemy.speed * dt;
    enemy.x += enemy.vx;
    enemy.y += enemy.vy;
    if (GF.math.dist(enemy.x, enemy.y, player.x, player.y) < player.radius + enemy.radius) {
      player.health -= 10;
      game.flash('#FF0000', 0.5);
      game.shake(5, 0.3);
      game.hitStop(0.1);
      enemies.splice(enemies.indexOf(enemy), 1);
      game.addScore(10);
    }
  }
}

function drawBackground(ctx) {
  const gradient = ctx.createLinearGradient(0, 0, 0, game.H);
  gradient.addColorStop(0, '#202020');
  gradient.addColorStop(1, '#404040');
  ctx.fillStyle = gradient;
  ctx.fillRect(0, 0, game.W, game.H);

  // Starfield
  ctx.fillStyle = '#303030';
  for (let i = 0; i < 20; i++) {
    ctx.beginPath();
    ctx.arc(Math.random() * game.W, Math.random() * game.H, Math.random() * 3 + 1, 0, Math.PI * 2);
    ctx.fill();
  }

  // Geometric shapes
  ctx.fillStyle = '#404040';
  for (let i = 0; i < 5; i++) {
    ctx.fillRect(Math.random() * game.W, Math.random() * game.H, 50, 10);
  }
}

function drawPlayer(ctx) {
  ctx.fillStyle = player.color;
  ctx.strokeStyle = '#FFFFFF';
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.arc(player.x, player.y, player.radius, 0, Math.PI * 2);
  ctx.fill();
  ctx.stroke();
}

function drawEnemies(ctx) {
  for (const enemy of enemies) {
    ctx.fillStyle = enemy.color;
    ctx.strokeStyle = '#FFFFFF';
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.arc(enemy.x, enemy.y, enemy.radius, 0, Math.PI * 2);
    ctx.fill();
    ctx.stroke();
  }
}

function drawHUD(ctx) {
  GF.Draw.roundRect(ctx, 10, 10, 200, 50, 5, 'rgba(0,0,0,0.5)');
  GF.Draw.text(ctx, `Health: ${player.health}`, 20, 30, { size: 20, color: '#FFFFFF', align: 'left' });
  GF.Draw.text(ctx, `Score: ${game.score}`, 20, 50, { size: 20, color: '#FFFFFF', align: 'left' });
}

game.add('play', {
  init() {
    createEnemy();
    createEnemy();
  },
  reset() {
    player.x = game.W / 2;
    player.y = game.H / 2;
    player.health = 100;
    enemies.length = 0;
    createEnemy();
    createEnemy();
  },
  update(dt) {
    updatePlayer(dt);
    updateEnemies(dt);
    if (player.health <= 0) {
      game.gameOver({ message: 'You were destroyed!' });
    }
    if (Math.random() < 0.01) createEnemy();
    particles.update(dt);
  },
  draw(ctx) {
    drawBackground(ctx);
    drawPlayer(ctx);
    drawEnemies(ctx);
    drawHUD(ctx);
    particles.draw(ctx);
  }
});

game.titleScreen({
  subtitle: 'Press any key to start',
  onStart() {
    game.go('play');
  }
});
